templates.study/response_detail.html:
{% extends "base.html" %}
{% load static study_markdown study_links %}
{% block title %}{{ selected_prompt.text|truncatechars:50 }} · Heureux{% endblock %}

{% block content %}
{% include "study/partials/task_nav.html" %}
{% if personal_saved %}<div class="notice">{% if ee_response %}Réponse enregistrée.{% else %}Votre version personnelle a été enregistrée et sera utilisée pendant les révisions.{% endif %}</div>{% endif %}
{% if personal_reset and not ee_response %}<div class="notice">La réponse d'origine est de nouveau utilisée.</div>{% endif %}
<div class="detail-head{% if ee_response %} detail-head--compact{% endif %}">
  <p class="eyebrow">
    <a href="{% subject_url 'study:task_browse' part.slug task.slug %}">{% if ee_response %}Sujets par thème{% else %}Sujets &amp; réponses{% endif %}</a> ·
    <a class="link-with-icon" style="--icon-accent: {{ selected_prompt.theme.color }};" href="{% subject_group_url part.slug task.slug selected_prompt.theme.slug %}">{% include "study/partials/ui_icon.html" with name=selected_prompt.theme.icon only %}<span>{{ selected_prompt.theme.display_name }}</span></a>
    {% if ee_response %}
      · {{ ee_source_month.name }} 2025
    {% else %}
      · <a href="{% subject_group_url part.slug task.slug selected_prompt.theme.slug selected_prompt.family.slug %}">{{ selected_prompt.family.name }}</a>
    {% endif %}
    {% if response_content.is_personal and not ee_response %} · <span class="chip">Version personnelle</span>{% endif %}
  </p>
  <h1 class="detail-prompt">{% if ee_response %}{{ selected_prompt.theme.display_name }}{% else %}{{ selected_prompt.text }}{% endif %}</h1>
  {% if response_content.reformulation and not ee_response %}<p class="reform">« {{ response_content.reformulation }} »</p>{% endif %}
  {% if subject_hints %}<a class="btn btn--sm subject-hints-jump" href="#subject-hints-title">Voir les pistes</a>{% endif %}
</div>

{% include "study/partials/prompt_navigation.html" %}

<div class="detail-grid"{% if ee_response %} style="--subject-accent: {{ task.color }};"{% endif %}>
  <div class="answer-columns"{% if not ee_response %} data-annotation-root data-annotation-source-key="{% if oral_annotation_key %}{{ oral_annotation_key }}{% else %}response:{{ response.content_key }}{% endif %}"{% if oral_legacy_annotation_keys %} data-annotation-legacy-source-keys="{{ oral_legacy_annotation_keys }}"{% endif %}{% endif %}>
    {% if ee_response %}
      {% include "study/partials/ee_subject_consigne.html" with title_id="ee-tache-three-subject-title" summary_text="120–180 mots · Partie 1 : synthèse neutre (40–60) · Partie 2 : point de vue justifié (80–120)" subject_text=selected_prompt.text subject_source_id="ee-tache-three-subject-content" only %}

      {# Keep the nested response-card tags adjacent so historical annotation whitespace offsets remain unchanged. #}
      {% include "study/partials/ee_tache_three_annotation_root.html" %}
    {% else %}{# The edit pencil sits in the first card's label row; its wrapper is excluded so annotation offsets stay unchanged. #}
    {% if response_content.position %}
      <section class="card section-card">
        <div class="section-card__head"><div class="spine-label">Position</div>{% if can_edit_response %}<span class="section-card__tools" data-annotation-exclude>{% spaceless %}{% include "study/partials/oral_response_edit_button.html" %}{% endspaceless %}</span>{% endif %}</div>
        <p class="spine-text">{{ response_content.position }}</p>
      </section>
    {% endif %}

    {% if response_content.position_claire %}
      <section class="card section-card">
        <div class="section-card__head"><div class="spine-label">Introduction</div>{% if can_edit_response and not response_content.position %}<span class="section-card__tools" data-annotation-exclude>{% spaceless %}{% include "study/partials/oral_response_edit_button.html" %}{% endspaceless %}</span>{% endif %}</div>
        <p class="spine-text">{{ response_content.position_claire }}</p>
      </section>
    {% endif %}

    <section class="card section-card section-card--arguments">
      <div class="section-card__head"><div class="spine-label">Arguments développés</div>{% if can_edit_response and not response_content.position and not response_content.position_claire %}<span class="section-card__tools" data-annotation-exclude>{% spaceless %}{% include "study/partials/oral_response_edit_button.html" %}{% endspaceless %}</span>{% endif %}</div>
      {% for arg in arguments %}
        <article class="arg arg--full">
          <h2 class="arg__idea">
            <span class="arg__number">{{ arg.order }}</span>
            <span>{{ arg.idea }}</span>
          </h2>
          <div class="arg__parts">
            {% if arg.developpement %}
              <div class="arg__part">
                <div class="arg__part-label">Développement</div>
                <p>{{ arg.developpement }}</p>
              </div>
            {% endif %}
            {% if arg.exemple %}
              <div class="arg__part">
                <div class="arg__part-label">Exemple concret</div>
                <p>{{ arg.exemple }}</p>
              </div>
            {% endif %}
            {% if arg.consequence %}
              <div class="arg__part">
                <div class="arg__part-label">Conséquence</div>
                <p>{{ arg.consequence }}</p>
              </div>
            {% endif %}
          </div>
        </article>
      {% endfor %}
    </section>

    {% if response_content.nuance %}
      <section class="card section-card section-card--nuance">
        <div class="spine-label">Nuance</div>
        <p class="spine-text">{{ response_content.nuance }}</p>
      </section>
    {% endif %}

    {% if response_content.conclusion %}
      <section class="card section-card section-card--conclusion">
        <div class="spine-label">Conclusion</div>
        <p class="spine-text">{{ response_content.conclusion }}</p>
      </section>
    {% endif %}
    {% endif %}

  </div>

  {# Keep hints outside both annotation roots so saved text offsets stay unchanged. #}
  {% if subject_hints %}
  <div class="detail-side subject-hints-column">
  {% endif %}
  <aside class="detail-side" data-annotation-root data-annotation-source-key="subject-sidebar:{% if oral_annotation_key %}{{ selected_prompt.content_key }}{% else %}{{ response.content_key }}{% endif %}">
    <div class="card section-card response-sidebar-card response-sidebar-card--status">
      <div class="spine-label">Progression du sujet</div>
      {% include "study/partials/subject_progress_control.html" with subject_label=selected_prompt.text hide_help=True %}
      {% if card %}
        <div class="spine-label">Pratique de la réponse</div>
        <dl class="kv">
          {% if card.response_practice_started_at %}<div><dt>Commencée</dt><dd>{{ card.response_practice_started_at|date:"j M Y" }}</dd></div>{% endif %}
          <div><dt>Répétitions</dt><dd>{{ card.reps }}</dd></div>
          <div><dt>Oublis</dt><dd>{{ card.lapses }}</dd></div>
          <div><dt>Intervalle</dt><dd>{{ card.interval_days|floatformat:0 }} j</dd></div>
          <div><dt>Facilité</dt><dd>{{ card.ease|floatformat:2 }}</dd></div>
          {% if card.due %}<div><dt>Prochaine</dt><dd>{{ card.due|date:"j M Y" }}</dd></div>{% endif %}
        </dl>
      {% else %}
        <p class="muted">Aucune pratique de la réponse.</p>
      {% endif %}
      <div class="response-sidebar-actions">
        {% if can_edit_response %}
          <a class="btn btn--block" href="{% subject_url 'study:edit_response' part.slug task.slug selected_prompt.pk %}">{% if ee_response %}Modifier la réponse{% elif response_content.is_personal %}Modifier ma version{% else %}Personnaliser la réponse{% endif %}</a>
        {% endif %}
        <a class="btn btn--primary btn--block" href="{{ response_review_url }}">Pratiquer cette réponse</a>
        <a class="btn btn--block" href="{{ theme_review_url }}">Pratiquer ce thème</a>
        {% if vocabulary_review_url %}
          <a class="btn btn--block" href="{{ vocabulary_review_url }}">Pratiquer les vocabs</a>
        {% endif %}
      </div>
    </div>

    {% if ee_response and ee_equivalent_subjects %}
      <div class="card section-card response-sidebar-card response-sidebar-card--aliases" id="equivalent-subjects">
        <div class="spine-label">Sujets équivalents</div>
        <p class="muted">Ces publications présentent des documents équivalents. La réponse et la progression sont partagées.</p>
        <ul class="mini-list">
          {% for equivalent in ee_equivalent_subjects %}
            <li>
              <a href="{% subject_url 'study:response_detail' part.slug task.slug equivalent.prompt.pk %}" target="_blank" rel="noopener noreferrer">
                <span class="chip">{{ equivalent.month.name }} 2025</span>
                {{ equivalent.prompt.text }}
              </a>
            </li>
          {% endfor %}
        </ul>
      </div>
    {% elif response.has_aliases %}
      <div class="card section-card response-sidebar-card response-sidebar-card--aliases" {% if part.slug == "ee" and task.slug == "tache-3" %}id="subject-equivalents"{% else %}id="subject-vocabulary"{% endif %}>
        <div class="spine-label">Sujets équivalents</div>
        <ul class="mini-list">
          {% for p in prompts %}
            <li>
              <a href="{% url 'study:response_detail' p.theme.task.part.slug p.theme.task.slug p.pk %}">
                <span class="chip chip--theme" style="--chip: {{ p.theme.color }};">{% include "study/partials/ui_icon.html" with name=p.theme.icon only %} P{{ p.number }}</span>
                {{ p.text }}
              </a>
            </li>
          {% endfor %}
        </ul>
      </div>
    {% endif %}

    {% if part.slug == "ee" and task.slug == "tache-3" %}
      <section class="card section-card" id="subject-vocabulary">
        <h2>Formulations</h2>
        <p>Le vocabulaire de cette tâche a été remplacé par des constructions à comprendre et à adapter.</p>
        <a class="btn" href="{% url 'study:ee_formulations' %}">Explorer les formulations</a>
      </section>
    {% endif %}
    {% if subject_vocabulary %}
      <div class="card section-card response-sidebar-card response-sidebar-card--vocabulary">
        <div class="response-batches__head">
          <div class="spine-label">Vocabulaire de ce sujet</div>
          <span class="progress-status progress-status--{{ vocabulary_batch_progress.status }}">{{ vocabulary_batch_progress.label }}</span>
        </div>
        <p class="muted">{{ vocabulary_batch_progress.completed }}/{{ vocabulary_batch_progress.total }} lots terminés</p>
        {% include "study/partials/vocabulary_recall_controls.html" with catalog_id="response-subject-vocabulary-recall-catalog" only %}
        <ul
          class="mini-list response-sidebar-list"
          id="response-subject-vocabulary-recall-catalog"
          data-recall-catalog
        >
          {% for phrase in subject_vocabulary %}
            {% include "study/partials/vocabulary_recall_list_item.html" with phrase=phrase recall_prefix="response-subject-vocabulary" only %}
          {% endfor %}
        </ul>
        {% include "study/partials/response_batch_list.html" with batches=vocabulary_batches batch_kind="vocabulary" only %}
      </div>
    {% endif %}

    {% if related_phrases %}
      <div class="card section-card response-sidebar-card response-sidebar-card--phrases">
        <div class="response-batches__head">
          <div class="spine-label">Expressions liées</div>
          <span class="progress-status progress-status--{{ phrase_batch_progress.status }}">{{ phrase_batch_progress.label }}</span>
        </div>
        <p class="muted">{{ phrase_batch_progress.completed }}/{{ phrase_batch_progress.total }} lots terminés</p>
        {% include "study/partials/vocabulary_recall_controls.html" with catalog_id="response-related-vocabulary-recall-catalog" only %}
        <ul
          class="mini-list response-sidebar-list"
          id="response-related-vocabulary-recall-catalog"
          data-recall-catalog
        >
          {% for phrase in related_phrases %}
            {% include "study/partials/vocabulary_recall_list_item.html" with phrase=phrase recall_prefix="response-related-vocabulary" only %}
          {% endfor %}
        </ul>
        {% include "study/partials/response_batch_list.html" with batches=phrase_batches batch_kind="expressions" only %}
      </div>
    {% endif %}
  </aside>
  {% if subject_hints %}
    {% include "study/partials/speaking_hints.html" with hints=subject_hints only %}
  </div>
  {% endif %}
</div>

{% include "study/partials/prompt_navigation.html" with bottom=True %}
{% if ee_response %}
  {{ ee_subject_copy_text|json_script:"ee-tache-three-subject-content" }}
  {{ ee_response_copy_text|json_script:"ee-tache-three-response-content" }}
{% endif %}
{% endblock %}

{% block scripts %}
  {{ block.super }}
  {% include "study/partials/subject_progress_script.html" %}
  {% if ee_response %}<script src="{% static 'study/js/prompt-copy.js' %}?v=3"></script>{% endif %}
{% endblock %}

templates.study/partials/card_front.html:
{% if kind == "spine" %}
  <div class="flashcard__head">
    <span class="flashcard__type">{{ kind_label }}</span>
    <span class="chip chip--theme" style="background: {{ theme.color }};">{% include "study/partials/ui_icon.html" with name=theme.icon only %} {{ theme.display_name }}</span>
    <span class="chip">{{ family_label|truncatechars:34 }}</span>
    <span class="progress-status progress-status--{{ subject_progress.status }}">{{ subject_progress.label }}</span>
  </div>
  <p class="prompt-text" data-read-aloud-text lang="fr">{{ prompt }}</p>{% if subject_prompt_note %}{% include "study/partials/tache_two_prompt_note.html" %}{% endif %}
  <div class="instruction">
    {% if tache_two_subject %}
      {% if aliases %}<div>{% include "study/partials/ui_icon.html" with name="arrow-left-right" only %} {{ aliases|length }} sujet{{ aliases|length|pluralize }} équivalent{{ aliases|length|pluralize }}</div>{% endif %}
      <div>À voix haute : <b>saluez, posez vos questions, rebondissez sur les réponses et terminez en remerciant</b>.</div>
    {% else %}
      {% if aliases %}<div>{% include "study/partials/ui_icon.html" with name="arrow-left-right" only %} {{ aliases|length }} formulation{{ aliases|length|pluralize }} équivalente{{ aliases|length|pluralize }}</div>{% endif %}
      <div>À voix haute : <b>reformulation → position → 3 arguments → nuance → conclusion</b>.</div>
    {% endif %}
  </div>
{% else %}
  <div class="flashcard__head">
    <span class="flashcard__type">{{ kind_label }}</span>
    <span class="chip">{{ category.name|truncatechars:34 }}</span>
    <span class="progress-status progress-status--{{ card.progress_status }}">{{ card.progress_label }}</span>
  </div>
  {% if production %}
    <p class="cue-text">{{ phrase.english_cue }}</p>
    <p class="cue-hint">{% if subject_vocabulary or theme_vocabulary or comprehension_vocabulary %}Produisez le mot, la tournure ou la phrase française{% else %}Produisez l'expression française{% endif %}, puis complétez :<br>« {{ cloze_example }} »</p>
  {% else %}
    <p class="cue-text serif" data-read-aloud-text lang="fr">{{ phrase.expression }}</p>
    <p class="cue-hint">Que signifie cette expression, et quand l'employer ?</p>
  {% endif %}
{% endif %}

templates.study/partials/card_back.html:
{% if kind == "spine" %}
  <div class="answer"{% if not tache_two_subject %} data-read-aloud-text{% endif %} lang="fr">
    {% if tache_two_subject %}
      {% if tache_two_dialogue %}
        <div class="spine-block">
          <div class="spine-label">Questions et relances · {{ subject_questions|length }} questions, relances comprises</div>
          {% include "study/partials/tache_two_dialogue_body.html" %}
        </div>
      {% else %}
      <div class="spine-block">
        <div class="spine-label">Questions à poser</div>{% if response_content.reformulation %}<p class="eo2-personal-boundary" data-read-aloud-text lang="fr">{{ response_content.reformulation|linebreaksbr }}</p>{% endif %}
        <ol class="flashcard-question-list">
          {% for arg in arguments %}
            <li>
              <span data-question-highlight-text="{{ forloop.counter }}" data-read-aloud-text lang="fr">{{ arg.idea|linebreaksbr }}</span>
            </li>
          {% endfor %}
        </ol>{% if response_content.conclusion %}<p class="eo2-personal-boundary" data-read-aloud-text lang="fr">{{ response_content.conclusion|linebreaksbr }}</p>{% endif %}
      </div>
      {% endif %}
      {% if aliases %}
        <div class="spine-block" style="margin-top:1rem;">
          <div class="spine-label">Sujets équivalents</div>
          <ul class="muted" style="margin:0.3rem 0 0; padding-left:1.1rem;">
            {% for a in aliases %}<li><b>{{ a.theme.display_name }} · Sujet {{ a.number }}</b> — {{ a.text }}</li>{% endfor %}
          </ul>
        </div>
      {% endif %}
    {% else %}
      <div class="spine-block">
        <div class="spine-label">Reformulation</div>
        <div class="spine-text">{{ response_content.reformulation }}</div>
      </div>
      <div class="spine-block">
        <div class="spine-label">Position</div>
        <div class="spine-text">{{ response_content.position }}</div>
      </div>
      {% for arg in arguments %}
        <div class="arg">
          <div class="arg__idea">{{ forloop.counter }}. {{ arg.idea }}</div>
        </div>
      {% endfor %}
      <div class="spine-block">
        <div class="spine-label">Nuance</div>
        <div class="spine-text">{{ response_content.nuance }}</div>
      </div>
      <div class="spine-block">
        <div class="spine-label">Conclusion</div>
        <div class="spine-text">{{ response_content.conclusion }}</div>
      </div>

      {% if aliases %}
        <div class="spine-block" style="margin-top:1rem;">
          <div class="spine-label">Formulations équivalentes</div>
          <ul class="muted" style="margin:0.3rem 0 0; padding-left:1.1rem;">
            {% for a in aliases %}<li><b>{{ a.theme.display_name }} P{{ a.number }}</b> — {{ a.text }}</li>{% endfor %}
          </ul>
        </div>
      {% endif %}
    {% endif %}

    {% if canonical_prompt %}
      <p style="margin-top:1rem;">
        <a class="chip" href="{{ detail_url }}">Ouvrir la fiche {% include "study/partials/ui_icon.html" with name="external-link" only %}</a>
      </p>
    {% endif %}
  </div>
{% else %}
  <div class="answer">
    {% if production %}
      <div class="spine-block">
        <div class="spine-label">{% if subject_vocabulary or theme_vocabulary or comprehension_vocabulary %}Réponse française{% else %}Expression{% endif %}</div>
        <div class="spine-text serif" data-read-aloud-text lang="fr">{{ phrase.expression }}</div>
      </div>
    {% else %}
      <div class="spine-block">
        <div class="spine-label">Sens / fonction</div>
        <div class="spine-text">{{ phrase.english_cue }}</div>
      </div>
    {% endif %}
    <div class="example-box" data-read-aloud-text lang="fr">{{ example_html|safe }}</div>
    {% if phrase.note %}<p class="phrase__note">{{ phrase.note }}</p>{% endif %}
    {% if sources and not theme_vocabulary %}
      <div class="phrase__foot">
        <span class="faint">Tiré de :</span>
        {% for s in sources|slice:":6" %}
          <a class="chip" href="{{ s.detail_url }}">{{ s.theme.display_name }} · {% if s.theme.task.slug == "tache-2" %}Sujet {{ s.number }}{% else %}P{{ s.number }}{% endif %}</a>
        {% endfor %}
        {% with more=sources|slice:"6:"|length %}{% if more %}<span class="chip chip--more">+{{ more }}</span>{% endif %}{% endwith %}
      </div>
    {% endif %}
    {% if question_sources %}
      <div class="phrase__foot">
        <span class="faint">Tiré de :</span>
        {% for source in question_sources %}
          <a class="chip" href="{% if source.test.mode == 'orale' %}{% url 'study:comprehension_oral_question_study' source.test.slug source.number %}{% else %}{% url 'study:comprehension_question_study' source.test.slug source.number %}{% endif %}">{{ source.test.title }} · Q{{ source.number }}</a>
        {% endfor %}
      </div>
    {% endif %}
  </div>
{% endif %}
